    int n = s.size();
    int m = t.size();

    if (n != m) {
        cout << -1 << endl;
        return 0;
    }

    vector<int> cnt(26);
    for (char c : s) {
        cnt[c - 'a']++;
    }

    for (char c : t) {
        cnt[c - 'a']--;
    }

    bool ok = true;
    for (int i = 0; i < 26; i++) {
        if (cnt[i] != 0) {
            ok = false;
            break;
        }
    }

    if (!ok) {
        cout << -1 << endl;
        return 0;
    }

    // Check if the order of characters in t matches a subsequence of s
    int j = 0;
    for (int i = 0; i < n && j < m; i++) {
        if (s[i] == t[j]) {
            j++;
        }
    }

    if (j == m) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }

    return 0;
}

