class RBTree {
  late Node root;

  void insertNode(int val) {
    if (root == null) {
      root = Node(val);
      return;
    }

    _insert(root, Node(val));
  }

  void _insert(Node node, Node newNode) {
    if (newNode.value < node.value) {
      if (node.left != null) {
        _insert(node.left!, newNode);
      } else {
        node.left = newNode;
      }
    } else {
      if (node.right != null) {
        _insert(node.right!, newNode);
      } else {
        node.right = newNode;
      }
    }
  }
}

