  int m = floor((pi * pow(n, 3)) / 6);
  double result = 0.0;
  for (int k = 0; k <= m; k++) {
    double term = pow(-1, k) * p * pow(pi, 6 * k + 3) * binomial(m, k) / ((pow(24, k) * factorial(k)));
    result += term;
  }
  return result;
}

// Helper function to compute binomial coefficients
int binomial(int n, int k) {
  if (k > n - k) {
    k = n - k;
  }
  int result = 1;
  for (int i = 0; i < k; i++) {
    result *= (n - i);
    result /= (i + 1);
  }
  return result;
}

// Helper function to compute factorial
int factorial(int n) {
  int result = 1;
  for (int i = 2; i <= n; i++) {
    result *= i;
  }
  return result;
}

