class Permutation {
  List<int> _p;

  factory Permutation(int n) => Permutation._(n, []);
  Permutation._(this.n, this._p) : assert(_p.length == n);

  int get length => _p.length;
  bool operator ==(Object other) => identical(this, other) || other is Permutation && runtimeType == other.runtimeType && _p == other.p;
  @override
  String toString() => p.join(' ');

  // return a new permutation of the same value as `this` but with element i and j swapped.
  Permutation swap(int i, int j) {
    if (i >= length || j >= length) throw ArgumentError('index out of bounds');
    final q = [..._p];
    final t = q[i];
    q[i] = q[j];
    q[j] = t;
    return Permutation(n, q);
  }

  /// apply this permutation to each item in x
  List<T> map<U>({int Function(T,U)? f, Iterable<U>? x}){ 
      if(x==null){return null;}
      return <U>[for(var y in x)f!(y,this)];}


  // return true iff every cycle in the permutation has even length
  bool hasEvenCycles(){var i=0,l=n/2;while(i<n){if(p[l]==i&&p[n-l-1]!=l)return false;i=l;l=i;n-=2;}return true;}


  // return one line notation from cycles notation
  static String createOneLine(String s) {
    var res = [s[0]];
    for (var i = 1; i < s.length; ++i) {
      if (s[i] != ',') continue;
      var cur = '';
      while (++i < s.length && s[i] != ')') {
        cur += s[i];
      }
      for (var j = 0; j < cur.length - 1; ++j) {
        res[res.indexOf(cur[j])] = cur[++j];
      }
    }
    return res.join(' ');
  }



  // convert this permutation into disjoint cycle notation
  void cyclesInverse(List<String> target) {
    var r = [];
