double distancePointLine(Vector point, Vector lineStart, Vector lineEnd) {
  // Calculate the difference vector between line start and end points.
  Vector dir = lineEnd.subtract(lineStart);

  // Normalize this direction vector by dividing it with its magnitude (length).
  double lenDirSquared = dir.x * dir.x + dir.y * dir.y;
  if (lenDirSquared == 0) return Double.NEGATIVE_INFINITY;
  double invLenDir = 1 / Math.sqrt(lenDirSquared);

  // Compute dot product of (point - lineStart) with normalized direction.
  double tDotPmS = dir.x * (point.x - lineStart.x) + dir.y * (point.y - lineStart.y);
  tDotPmS *= invLenDir;

  // Find closest position on segment using clamped parameter 't'.
  int clampValue = 0;
  if (tDotPmS < 0) clampValue = -1;
  else if (tDotPmS > 1) clampValue = 1;

  Vector closestPosOnSegment = new Vector(
    lineStart.x + clampValue * dir.x * invLenDir,
    lineStart.y + clampValue * dir.y * invLenDir
  );

  // Return Euclidean distance from point to that nearest location.
  return point.distance(closestPosOnSegment);
}

