int deBruijn(int n, int k) {
    if (k == 0) return 1;

    List<int> arr = new List<int>(n / k + 1);
    for (int i = 0; i < arr.length; ++i) {
        arr[i] = 0;
    }

    for (int i = 0; i <= arr.length - 1; ++i) {
        int x = i % k;

        arr[x]++;

        while ((arr[x] > 1 && x < k) || (x >= k)) {
            x--;
            --arr[x];

            if (x < 0) break;
        }

        int value = 0;
        for (int j = 0; j < arr.length; ++j) {
            value += arr[j] * Math.pow(n, j);
        }

        if (value >= Math.pow(n, k)) break;
    }

    return arr[0];
}

