class Solution {
  List<int> findDartboard(List<List<String>> coordinates) {
    final Set<int> hits = {};

    for (final List<String> coord in coordinates) {
      if (coord[0].length == 1 && int.parse(coord[0]) <= 9) {
        hits.add(int.parse(coord.join('')));
      } else if (coord.length > 2) {
        var hitNumber = '';

        for (var i = 0; i < coord.length - 2; i++) {
          hitNumber += coord[i];
        }

        if (int.tryParse(hitNumber) != null) {
          hits.add(int.parse(hitNumber));
        }
      }
    }

    return hits.toList();
  }
}

