void lineout(int n) {
  int arr[] = new int[n];

  for (int i = 0; i < n - 1; i++) {
    arr[i] = i + 2;
  }

  if ((n % 2) != 0) {
    // If odd, then the last element is equal to half of sum of first and last
    // two elements.

    arr[n-1] = (arr[0]+arr[arr.length-1])/2;

  } else {
    // Otherwise it's just a regular arithmetic progression with difference of 
    // one.
    arr[n-1] = arr[0] + n - 1;
  }

}

