void lineout(List<int> input, List<String> output) {
  if (input.isEmpty) return;

  int length = input.length - 1;

  // First half
  for (int i = 0; i <= length ~/2; ++i) {
    output.add(input[i]);
  }

  // Second half in reverse order
  for (int i = length; i >= length ~/2 + 1; --i) {
    output.add(input[i]);
  }
}

